<?php
declare(strict_types=1);namespace Liberu\Accounting\FixedAssets\Models;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\HasMany;use Liberu\Accounting\FixedAssets\Enums\AssetStatus;/** @property AssetStatus $status @property string $cost @property string $net_book_value */final class Asset extends Model {protected $table='accounting_fixed_assets';protected $fillable=['team_id','asset_ref','name','category_id','status','acquired_on','capitalized_on','cost','salvage_value','net_book_value','currency','location_ref','custodian_ref','metadata'];protected $casts=['status'=>AssetStatus::class,'acquired_on'=>'date','capitalized_on'=>'date','cost'=>'decimal:2','salvage_value'=>'decimal:2','net_book_value'=>'decimal:2','metadata'=>'array'];public function category():\Illuminate\Database\Eloquent\Relations\BelongsTo{return $this->belongsTo(AssetCategory::class,'category_id');}public function components():HasMany{return $this->hasMany(AssetComponent::class,'asset_id');}public function books():HasMany{return $this->hasMany(AssetBook::class,'asset_id');}public function documents():HasMany{return $this->hasMany(AssetDocument::class,'asset_id');}}
